<?php
require_once __DIR__ . '/config/database.php';
$unitId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
$unit = null; $apartment = null; $gallery = []; $dbError = null;
try {
    $pdo = db();
    $statement = $pdo->prepare('SELECT * FROM units WHERE id = :id LIMIT 1');
    $statement->execute(['id' => $unitId ?: 0]); $unit = $statement->fetch();
    if ($unit) {
        $statement = $pdo->prepare('SELECT * FROM apartments WHERE id = :id LIMIT 1');
        $statement->execute(['id' => $unit['apartment_id']]); $apartment = $statement->fetch();
        $statement = $pdo->prepare('SELECT image_path, caption, sort_order FROM unit_images WHERE unit_id = :unit_id ORDER BY sort_order ASC');
        $statement->execute(['unit_id' => $unit['id']]); $gallery = $statement->fetchAll();
        if (!empty($unit['image_url'])) array_unshift($gallery, ['image_path' => $unit['image_url'], 'caption' => 'Main view']);
    }
} catch (Throwable $exception) { $dbError = 'The unit details need the MySQL connection. Import sql/staylocal.sql in XAMPP, then try again.'; }
if (!$unit && $dbError === null) http_response_code(404);
$pageTitle = $unit ? 'Unit ' . $unit['unit_number'] . ' at ' . $apartment['name'] : 'Unit details';
$currentPage = 'homes'; require __DIR__ . '/partials/header.php';
?>
