<?php elseif (!$unit): ?><div class="empty-state detail-empty"><p class="eyebrow">UNIT NOT FOUND</p><h1>This unit has moved on.</h1><p>Return to the apartment listing to see other available units.</p><a class="button button-dark" href="index.php">Back to apartments</a></div>
